const body = $json.body ?? $json;
if (!body || typeof body !== 'object') throw new Error('A JSON request body is required');
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : (r & 3) | 8).toString(16);
});
const message = String(body.message ?? body.data?.message ?? '').trim();
if (message.length < 2 || message.length > 500) throw new Error('message must contain 2-500 characters');
return [{ json: { message, correlationId: body.correlationId || uuid(), actor: body.actor || null, cycleId: body.cycleId || body.data?.cycleId || null } }];

const raw = String($json.output ?? '').trim();
const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const jsonText = start >= 0 && end >= start ? raw.slice(start, end + 1) : raw;
let value;
try { value = JSON.parse(jsonText); } catch { value = { responseType: 'ERROR', message: 'The assistant returned an invalid response. Please try again.', requiresConfirmation: false }; }
const allowedTypes = ['ANSWER','CLARIFICATION','CART_PROPOSAL','NO_MATCH','REFUSAL','ERROR'];
if (!allowedTypes.includes(value.responseType)) value.responseType = 'ERROR';
value.correlationId = $('Normalize Agent Request').first().json.correlationId;
value.message = String(value.message || 'The request could not be completed.').slice(0, 800);
value.candidates = Array.isArray(value.candidates) ? value.candidates.slice(0, 5).map(c => ({ productId: c.productId || c.product?.productId, name: c.name || c.product?.name || 'Product', similarityScore: c.similarityScore ?? null })).filter(c => /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(c.productId || ''))) : [];
if (value.responseType === 'CART_PROPOSAL') {
  const input = value.proposal || {};
  const actionMap = { ADD: 'ADD_ITEM', ADD_ITEM: 'ADD_ITEM', MERGE: 'MERGE_ITEMS', MERGE_ITEMS: 'MERGE_ITEMS', SUBSTITUTE: 'SUBSTITUTE_ITEM', SUBSTITUTE_ITEM: 'SUBSTITUTE_ITEM' };
  const action = actionMap[input.action];
  const productId = input.productId || input.product?.productId;
  const quantity = Number(input.quantity);
  const replacesProductId = input.replacesProductId || input.replacesProduct?.productId || null;
  const validProduct = /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(productId || ''));
  const validQuantity = Number.isInteger(quantity) && quantity >= 1 && quantity <= 99;
  if (!action || !validProduct || !validQuantity) {
    value = { responseType: 'ERROR', message: 'A valid proposal could not be created.', requiresConfirmation: false, correlationId: value.correlationId, proposal: null, candidates: value.candidates };
  } else {
    value.proposal = { action, productId, quantity, replacesProductId };
    value.requiresConfirmation = true;
  }
} else {
  value.requiresConfirmation = false;
  value.proposal = null;
}
return [{ json: value }];
